func renderReleasePlanResponse(cmd *cobra.Command, flags *rootFlags, payload releasePlanResponse) error {
	asJSON := flags.asJSON || flags.agent || !isTerminal(cmd.OutOrStdout())
	if asJSON {
		return printJSONFiltered(cmd.OutOrStdout(), payload, flags)
	}

	w := cmd.OutOrStdout()
	if payload.Surface == "" {
		fmt.Fprintln(w, "Release plan")
		fmt.Fprintln(w, "Safety: local guidance only. No publish, push, upload, signing, notarization, external service calls, MCP execution, or secret reads.")
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Surfaces:")
		for _, surface := range payload.AvailableSurfaces {
			fmt.Fprintf(w, "  %s\n", surface)
		}
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Blockers:")
		for _, blocker := range payload.Blockers {
			fmt.Fprintf(w, "  %s\n", blocker)
		}
		return nil
	}
	if payload.Surface == "all" {
		fmt.Fprintln(w, "Release plan: all")
		fmt.Fprintln(w, "Safety: local guidance only. Public launch still needs approvals and distribution decisions.")
		for _, plan := range payload.SurfacePlans {
			fmt.Fprintf(w, "  %s - %s\n", plan.Name, plan.Summary)
		}
		return nil
	}

	plan := payload.SurfacePlan
	fmt.Fprintf(w, "Release plan: %s\n", plan.Name)
	fmt.Fprintln(w, "Safety: local guidance only. No release action happens here.")
	fmt.Fprintln(w, "Local proof:")
	for _, command := range plan.LocalProofCommands {
		fmt.Fprintf(w, "  %s\n", command)
	}
	fmt.Fprintln(w, "Blockers:")
	for _, blocker := range plan.Blockers {
		fmt.Fprintf(w, "  %s\n", blocker)
	}
	return nil
}

